import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_src = r'''
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define BM 64
#define BN 64
#define BK 32
#define SPLIT_K 32
#define SKEW_A 1
#define SKEW_B 1
// Split-K tiled matmul: C = A * B
// A: (M, K) row-major, B: (K, N) row-major, C: (M, N) row-major
// K is very large while M and N are small, so we partition K across
// gridDim.z blocks. This version uses thread-level register tiling:
// each 16x16 thread block computes a 64x64 C tile and each thread
// accumulates a 4x4 register block, with float4 global loads when aligned.
__global__ void matmul_splitk_kernel(const float* __restrict__ A,
                                     const float* __restrict__ B,
                                     float* __restrict__ C,
                                     int M, int N, int K) {
    int num_k_tiles = (K + BK - 1) / BK;
    int tiles_per_split = (num_k_tiles + gridDim.z - 1) / gridDim.z;
    int k_start = blockIdx.z * tiles_per_split * BK;
    int k_end = min(K, k_start + tiles_per_split * BK);
    if (k_start >= k_end) return;
    int tile_row = blockIdx.y * BM;
    int tile_col = blockIdx.x * BN;
    int row0 = tile_row + threadIdx.y * 4;
    int col0 = tile_col + threadIdx.x * 4;
    __shared__ float As[BM][BK + SKEW_A];
    __shared__ float Bs[BK][BN + SKEW_B];
    float acc[4][4];
    #pragma unroll
    for (int i = 0; i < 4; ++i) {
        #pragma unroll
        for (int j = 0; j < 4; ++j) {
            acc[i][j] = 0.0f;
        }
    }
    const int tid = threadIdx.y * 16 + threadIdx.x;
    const int nthreads = 256;
    const int a_f4 = (BM * BK) / 4;
    const int b_f4 = (BK * BN) / 4;
    const bool a_vec = ((K & 3) == 0);
    const bool b_vec = ((N & 3) == 0);
    for (int t = k_start; t < k_end; t += BK) {
        for (int f = tid; f < a_f4; f += nthreads) {
            int r = f / (BK / 4);
            int q = f % (BK / 4);
            int c = q * 4;
            int gr = tile_row + r;
            int gc = t + c;
            float x0 = 0.0f, x1 = 0.0f, x2 = 0.0f, x3 = 0.0f;
            if (gr < M) {
                if (a_vec && gc + 3 < k_end) {
                    float4 v = *reinterpret_cast<const float4*>(A + (long)gr * K + gc);
                    x0 = v.x; x1 = v.y; x2 = v.z; x3 = v.w;
                } else {
                    x0 = (gc < k_end) ? A[(long)gr * K + gc] : 0.0f;
                    x1 = (gc + 1 < k_end) ? A[(long)gr * K + gc + 1] : 0.0f;
                    x2 = (gc + 2 < k_end) ? A[(long)gr * K + gc + 2] : 0.0f;
                    x3 = (gc + 3 < k_end) ? A[(long)gr * K + gc + 3] : 0.0f;
                }
            }
            As[r][c] = x0;
            As[r][c + 1] = x1;
            As[r][c + 2] = x2;
            As[r][c + 3] = x3;
        }
        for (int f = tid; f < b_f4; f += nthreads) {
            int r = f / (BN / 4);
            int q = f % (BN / 4);
            int c = q * 4;
            int gr = t + r;
            int gc = tile_col + c;
            float x0 = 0.0f, x1 = 0.0f, x2 = 0.0f, x3 = 0.0f;
            if (gr < k_end) {
                if (b_vec && gc + 3 < N) {
                    float4 v = *reinterpret_cast<const float4*>(B + (long)gr * N + gc);
                    x0 = v.x; x1 = v.y; x2 = v.z; x3 = v.w;
                } else {
                    x0 = (gc < N) ? B[(long)gr * N + gc] : 0.0f;
                    x1 = (gc + 1 < N) ? B[(long)gr * N + gc + 1] : 0.0f;
                    x2 = (gc + 2 < N) ? B[(long)gr * N + gc + 2] : 0.0f;
                    x3 = (gc + 3 < N) ? B[(long)gr * N + gc + 3] : 0.0f;
                }
            }
            Bs[r][c] = x0;
            Bs[r][c + 1] = x1;
            Bs[r][c + 2] = x2;
            Bs[r][c + 3] = x3;
        }
        __syncthreads();
        #pragma unroll
        for (int k = 0; k < BK; ++k) {
            float a_frag[4];
            float b_frag[4];
            #pragma unroll
            for (int i = 0; i < 4; ++i) {
                a_frag[i] = As[threadIdx.y * 4 + i][k];
            }
            #pragma unroll
            for (int j = 0; j < 4; ++j) {
                b_frag[j] = Bs[k][threadIdx.x * 4 + j];
            }
            #pragma unroll
            for (int i = 0; i < 4; ++i) {
                #pragma unroll
                for (int j = 0; j < 4; ++j) {
                    acc[i][j] += a_frag[i] * b_frag[j];
                }
            }
        }
        __syncthreads();
    }
    #pragma unroll
    for (int i = 0; i < 4; ++i) {
        int r = row0 + i;
        if (r < M) {
            #pragma unroll
            for (int j = 0; j < 4; ++j) {
                int c = col0 + j;
                if (c < N) {
                    atomicAdd(&C[(long)r * N + c], acc[i][j]);
                }
            }
        }
    }
}
torch::Tensor matmul(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda() && B.is_cuda());
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2);
    TORCH_CHECK(A.size(1) == B.size(0));
    int M = A.size(0);
    int K = A.size(1);
    int N = B.size(1);
    auto C = torch::zeros({M, N}, A.options());
    dim3 block(16, 16);
    dim3 grid((N + BN - 1) / BN, (M + BM - 1) / BM, SPLIT_K);
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    matmul_splitk_kernel<<<grid, block, 0, stream>>>(
        A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), M, N, K);
    return C;
}
'''

cpp_src = "torch::Tensor matmul(torch::Tensor A, torch::Tensor B);"

matmul_op = load_inline(
    name="matmul_splitk_ext",
    cpp_sources=cpp_src,
    cuda_sources=cuda_src,
    functions=["matmul"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Matrix multiplication (C = A * B) optimized for a very large K dimension
    using a custom split-K CUDA kernel with shared-memory tiling and atomic
    accumulation of partial products.
    """
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        if not A.is_cuda:
            A = A.cuda()
        if not B.is_cuda:
            B = B.cuda()
        A = A.contiguous().float()
        B = B.contiguous().float()
        return matmul_op.matmul(A, B)

